use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Reg { pub fn align < C : HasDataLayout > (& self , cx : & C) -> Align { let dl = cx . data_layout () ; match self . kind { RegKind :: Integer => match self . size . bits () { 1 => dl . i1_align . abi , 2 ..= 8 => dl . i8_align . abi , 9 ..= 16 => dl . i16_align . abi , 17 ..= 32 => dl . i32_align . abi , 33 ..= 64 => dl . i64_align . abi , 65 ..= 128 => dl . i128_align . abi , _ => panic ! ("unsupported integer: {self:?}") , } , RegKind :: Float => match self . size . bits () { 16 => dl . f16_align . abi , 32 => dl . f32_align . abi , 64 => dl . f64_align . abi , 128 => dl . f128_align . abi , _ => panic ! ("unsupported float: {self:?}") , } , RegKind :: Vector => dl . llvmlike_vector_align (self . size) . abi , } } }